        date('now', 'localtime', '+24 days'), date('now', 'localtime', '+70 days'), 'P', 'Lồng tiếng Việt',
        'Những cảm xúc mới như Lo Âu, Ganh Tị xuất hiện khi cô bé Riley bước vào độ tuổi thiếu niên đầy biến động.', 'Posters/inside-out-2.jpg', 'ComingSoon'),
    (15, 'Ngày Xưa Có Một Chuyện Tình', 'Once Upon a Love Story', 'Trịnh Đình Lê Minh', 'Avin Lu, Ngọc Xuân, Đỗ Nhật Hoàng', 135,
        date('now', 'localtime', '+28 days'), date('now', 'localtime', '+72 days'), 'T13', 'Tiếng Việt',
        'Chuyện tình bạn thanh mai trúc mã trải dài qua những năm tháng trưởng thành đầy hoài niệm và day dứt.', 'Posters/ngay-xua-chuyen-tinh.jpg', 'ComingSoon');

